if(!defined('APP_ROOT')){for($d=__DIR__,$i=0;$i<7;$i++,$d=dirname($d))if(is_file($d.'/app/Core/paths.php')){require_once $d.'/app/Core/paths.php';break;}}
require_once APP_ROOT.'/Core/config.php';require_once APP_ROOT.'/Modules/Tools/Services/ToolCalculator.php';require_once APP_ROOT.'/Modules/Tools/Services/SavedNumbersService.php';require_once APP_ROOT.'/Modules/Tools/Services/ToolResultMailer.php';require_once APP_ROOT.'/Services/Messaging/SmtpMailer.php';
