function answer(int $code,array $body):void{http_response_code($code);echo json_encode($body);exit;}
function limited(string $key,int $limit,int $seconds):bool{$dir=sys_get_temp_dir().'/ittai-tool-throttle';if(!is_dir($dir)&&!@mkdir($dir,0700,true)&&!is_dir($dir))return true;$file=$dir.'/'.hash('sha256',$key);$now=time();$times=[];$h=@fopen($file,'c+');if(!$h)return true;flock($h,LOCK_EX);$raw=stream_get_contents($h);foreach(explode("\n",(string)$raw)as $v)if((int)$v>$now-$seconds)$times[]=(int)$v;$hit=count($times)>=$limit;if(!$hit)$times[]=$now;ftruncate($h,0);rewind($h);fwrite($h,implode("\n",$times));fflush($h);flock($h,LOCK_UN);fclose($h);return $hit;}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')answer(405,['error'=>'Method not allowed']);if(!defined('ITTAI_MAIL_FROM')||(string)ITTAI_MAIL_FROM==='')answer(503,['error'=>'Email is not available.']);$b=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($b))answer(400,['error'=>'Invalid request']);
if(trim((string)($b['hp']??''))!==''||time()-((int)($b['t']??0)/1000)<3)answer(200,['message'=>'Sent']);$email=strtolower(trim((string)($b['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))answer(422,['error'=>'Enter a valid email.']);$tool=(string)($b['tool']??'');if(!in_array($tool,ToolCalculator::tools(),true))answer(422,['error'=>'Unknown calculator.']);$ip=(string)($_SERVER['REMOTE_ADDR']??'unknown');$eh=hash('sha256',$email);if(limited('ip:'.$ip,5,600)||limited('email-hour:'.$eh,3,3600)||limited('email-day:'.$eh,10,86400))answer(429,['error'=>'Too many tries. Please wait a few minutes.']);
