$saved=null;$confirm=null;$delete=null;$save=!empty($b['save']);if($save&&($db=Database::platform())){try{$saved=(new SavedNumbersService($db))->createPending($email,$tool,$inputs,!empty($b['news']),!empty($b['benchmarks']),'/tools/'.$tool.'/');$base='https://ittai.ca';$confirm=$base.'/tools/confirm/?t='.rawurlencode($saved['confirm_token']);$delete=$base.'/tools/delete/?t='.rawurlencode($saved['delete_token']);}catch(Throwable $e){error_log('Save pending failed: '.$e->getMessage());$saved=null;}}
$mail=(new ToolResultMailer($calculator))->render($tool,$inputs,$confirm,$delete);if(!sendPlatformEmail($email,$mail['subject'],$mail['html'],$mail['plain']))answer(503,['error'=>'Email could not be sent. Try again.']);$reply=['message'=>'Sent','saved'=>$save?($saved?'pending':'unavailable'):'not_requested'];if($save&&!$saved)$reply['message']="Saving isn't switched on yet; your result was sent.";answer(200,$reply);
